<script setup lang="ts">
import { computed, nextTick, onMounted, ref, watch } from 'vue'
import { ApiError, requestValidatedData, requestValidatedPage, requestVoid } from '../services/http'
import { isCatalog, isRule, isIncident, type Catalog, type Rule, type Incident } from '../services/management'
type Input={name:string;source:string;severity:string;selector:{metric:string;labels:Record<string,string>};reducer:string;operator:string;threshold:number;window:string;for:string;enabled?:boolean;revision?:number}
const catalog=ref<Catalog|null>(null),rules=ref<Rule[]>([]),incidents=ref<Incident[]>([]),tab=ref('rules'),busy=ref(false),message=ref(''),next=ref<string|null>(null),editing=ref<Rule|null>(null),showForm=ref(false)
const source=ref('metrics'),metric=ref(''),tuple=ref(0),name=ref(''),severity=ref('warning'),reducer=ref('last'),operator=ref('gt'),threshold=ref(0),windowSize=ref('1m'),forSize=ref('0s')
const definition=computed(()=>catalog.value?.metrics.find(m=>m.metric===metric.value))
const selectors=computed<Record<string,string>[]>(()=>{if(!catalog.value)return [];if(source.value==='metrics'){const d=definition.value;return d?d.allowed_tuples.map(t=>Object.fromEntries(d.label_keys.map((k,i)=>[k,t[i]!]))):[]}const c=source.value==='logs'?catalog.value.logs:catalog.value.events;return c.allowed_combinations.length?c.allowed_combinations:Object.entries(c.fields).flatMap(([k,vs])=>vs.map(v=>({[k]:v})))})
const reducers=computed(()=>source.value==='metrics'?definition.value?.reducers??[]:['count'])
const durations=computed(()=>catalog.value?.for.filter(v=>v==='0s'||v==='1m'||windowSize.value!=='1m')??[])
watch(source,()=>{tuple.value=0;reducer.value=source.value==='metrics'?'last':'count'})
watch(metric,()=>{tuple.value=0;reducer.value=definition.value?.reducers[0]??'last'})
watch(windowSize,()=>{if(!durations.value.some(v=>v===forSize.value))forSize.value='0s'})
async function load(more=false){if(busy.value)return;busy.value=true;message.value='';try{if(!catalog.value){catalog.value=await requestValidatedData('/alerts/catalog',isCatalog);metric.value=catalog.value.metrics[0]?.metric??''}const page=await requestValidatedPage<Rule|Incident>('/alerts/'+tab.value+(more&&next.value?'?cursor='+encodeURIComponent(next.value):''),tab.value==='rules'?isRule:isIncident);if(tab.value==='rules')rules.value=more?[...rules.value,...page.data as Rule[]]:page.data as Rule[];else incidents.value=more?[...incidents.value,...page.data as Incident[]]:page.data as Incident[];next.value=page.nextCursor}catch{message.value='告警读取失败'}finally{busy.value=false}}
async function selectTab(value:string){tab.value=value;next.value=null;incidents.value=[];await load()}
function create(){editing.value=null;name.value='';showForm.value=true}
async function edit(r:Rule){editing.value=r;source.value=r.source;metric.value=r.selector.metric;await nextTick();tuple.value=Math.max(0,selectors.value.findIndex(s=>JSON.stringify(Object.entries(s).sort())===JSON.stringify(Object.entries(r.selector.labels).sort())));name.value=r.name;severity.value=r.severity;reducer.value=r.reducer;operator.value=r.operator;threshold.value=r.threshold;windowSize.value=r.window;forSize.value=r.for;showForm.value=true}
async function failed(e:unknown){busy.value=false;if(e instanceof ApiError&&e.status===409){showForm.value=false;await load();message.value='已被其他管理员修改，请重新读取后操作。'}else message.value='操作失败，请检查规则或稍后重试。'}
async function save(){if(busy.value||!selectors.value[tuple.value])return;if(editing.value&&!window.confirm('更新会关闭当前 firing 告警并重置评估状态，确认更新？'))return;busy.value=true;try{const body:Input={name:name.value,source:source.value,severity:severity.value,selector:{metric:source.value==='metrics'?metric.value:'',labels:selectors.value[tuple.value]!},reducer:reducer.value,operator:operator.value,threshold:threshold.value,window:windowSize.value,for:forSize.value};if(editing.value)body.revision=editing.value.revision;else body.enabled=true;await requestValidatedData('/alerts/rules'+(editing.value?'/'+editing.value.id:''),isRule,{method:editing.value?'PUT':'POST',body:JSON.stringify(body)});showForm.value=false;busy.value=false;await load();message.value='规则已保存'}catch(e){await failed(e)}finally{busy.value=false}}
async function mutate(r:Rule,action:string){if(busy.value)return;if(action!=='enable'&&!window.confirm('此操作会关闭当前 firing 告警，确认'+action+'？'))return;busy.value=true;try{const init={method:action==='delete'?'DELETE':'POST',body:JSON.stringify({revision:r.revision})};const path='/alerts/rules/'+r.id+(action==='delete'?'':'/'+action);if(action==='delete')await requestVoid(path,init);else await requestValidatedData(path,isRule,init);busy.value=false;await load();message.value='操作成功'}catch(e){await failed(e)}finally{busy.value=false}}
onMounted(()=>load())
</script>
<template><section><h2>告警管理</h2><nav><button v-for="t in ['rules','current','history']" :key="t" :disabled="busy" @click="selectTab(t)">{{t}}</button></nav><p>时间区：{{Intl.DateTimeFormat().resolvedOptions().timeZone}}；unknown / stale 不表示 recovered。</p><p role="status">{{message}}</p><button :disabled="busy" @click="load()">刷新告警</button><template v-if="tab==='rules'"><button :disabled="busy||!catalog" @click="create">创建规则</button><form v-if="showForm&&catalog" @submit.prevent="save"><label>名称<input v-model="name" required maxlength="80" /></label><label>来源<select aria-label="来源" v-model="source"><option v-for="s in catalog.creatable_sources" :key="s">{{s}}</option></select></label><label v-if="source==='metrics'">指标<select aria-label="指标" v-model="metric"><option v-for="m in catalog.metrics" :key="m.metric">{{m.metric}}</option></select></label><label>固定选择器<select aria-label="固定选择器" v-model="tuple"><option v-for="(s,i) in selectors" :key="i" :value="i">{{JSON.stringify(s)}}</option></select></label><label>聚合<select aria-label="聚合" v-model="reducer"><option v-for="r in reducers" :key="r">{{r}}</option></select></label><label>运算<select aria-label="运算" v-model="operator"><option v-for="o in catalog.operators" :key="o">{{o}}</option></select></label><label>阈值<input v-model.number="threshold" type="number" step="any" required /></label><label>窗口<select aria-label="窗口" v-model="windowSize"><option v-for="w in catalog.windows" :key="w">{{w}}</option></select></label><label>持续<select aria-label="持续" v-model="forSize"><option v-for="f in durations" :key="f">{{f}}</option></select></label><label>严重度<select aria-label="严重度" v-model="severity"><option v-for="s in catalog.severities" :key="s">{{s}}</option></select></label><button :disabled="busy">保存规则</button><button type="button" @click="showForm=false">取消</button></form><p v-if="!busy&&!rules.length">暂无规则</p><article v-for="r in rules" :key="r.id" :data-rule-id="r.id"><h3>{{r.name}} · #{{r.id}} / revision {{r.revision}}</h3><p>{{r.source}} · {{r.severity}} · {{r.evaluation.state}} · {{r.evaluation.data_status}}</p><p>{{JSON.stringify(r.selector)}}</p><button :disabled="busy" @click="edit(r)">编辑</button><button :disabled="busy" @click="mutate(r,r.enabled?'disable':'enable')">{{r.enabled?'停用':'启用'}}</button><button :disabled="busy" @click="mutate(r,'delete')">删除</button></article></template><template v-else><p v-if="!busy&&!incidents.length">暂无告警记录</p><article v-for="r in incidents" :key="r.id"><h3>{{r.name}} · rule {{r.rule_id}} / revision {{r.revision}}</h3><p>{{r.severity}} · {{r.status}} · {{r.data_status}} · {{r.resolution_reason}}</p><p>{{JSON.stringify(r.object)}}</p><p>首次 {{new Date(r.first_triggered_at).toLocaleString()}} · 最近 {{new Date(r.last_triggered_at).toLocaleString()}}</p><p>值 {{r.last_value??'unknown'}} · 评估次数 {{r.evaluation_count}}</p><p>恢复 {{r.recovered_at?new Date(r.recovered_at).toLocaleString():'—'}} · 关闭 {{r.closed_at?new Date(r.closed_at).toLocaleString():'—'}}</p></article></template><button v-if="next" :disabled="busy" @click="load(true)">更多告警</button></section></template>
